'use strict';

const {
  DPIM_PHYSICAL,
  HDT_KM,
  HKM_IGNORE_VID_PID,
  getDefaultDllPath,
  isFail,
  loadBindings
} = require('./wyhkm-dll');
const {
  normalizeKey,
  normalizePlatform
} = require('./wyhkm-key-names');

const DEFAULT_OPTIONS = {
  deviceId: undefined,
  vid: HKM_IGNORE_VID_PID,
  pid: HKM_IGNORE_VID_PID,
  deviceType: HDT_KM,
  dpiMode: DPIM_PHYSICAL,
  edition: 'standard',
  dllPath: '',
  screenBounds: undefined,
  screenWidth: undefined,
  screenHeight: undefined,
  screenLeft: 0,
  screenTop: 0,
  clickHoldMs: 60,
  clickIntervalMs: 35,
  keyIntervalMinMs: undefined,
  keyIntervalMaxMs: undefined,
  logger: console
};

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function toBool(value) {
  return value === true || value === 1;
}

function toErrorCode(bindings, handle) {
  if (!bindings.HKMGetError) {
    return undefined;
  }
  try {
    return bindings.HKMGetError(handle || null);
  } catch (_error) {
    return undefined;
  }
}

function throwHkmError(message, bindings, handle) {
  const code = toErrorCode(bindings, handle);
  const suffix = typeof code === 'number' ? ` (HKM error 0x${code.toString(16)})` : '';
  throw new Error(`${message}${suffix}`);
}

function getHkmErrorMessage(message, bindings, handle) {
  const code = toErrorCode(bindings, handle);
  const suffix = typeof code === 'number' ? ` (HKM error 0x${code.toString(16)})` : '';
  return `${message}${suffix}`;
}

function normalizeClickOptions(value = {}, defaults = DEFAULT_OPTIONS) {
  const options = value && typeof value === 'object' ? value : {};
  const holdMs = Number(options.holdMs);
  const repeat = Number(options.repeat);
  const intervalMs = Number(options.intervalMs);

  return {
    holdMs: Number.isFinite(holdMs) && holdMs >= 0
      ? Math.round(holdMs)
      : defaults.clickHoldMs,
    repeat: Number.isFinite(repeat) && repeat > 0
      ? Math.max(1, Math.round(repeat))
      : 1,
    intervalMs: Number.isFinite(intervalMs) && intervalMs >= 0
      ? Math.round(intervalMs)
      : defaults.clickIntervalMs
  };
}

function normalizeButton(button) {
  if (button === 'right') return 'right';
  if (button === 'middle') return 'middle';
  return 'left';
}

function toFiniteNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : undefined;
}

function normalizeKeyIntervalOptions(options) {
  const min = toFiniteNumber(options.keyIntervalMinMs);
  const max = toFiniteNumber(options.keyIntervalMaxMs);

  if (min === undefined && max === undefined) {
    return null;
  }

  const normalizedMin = Math.max(0, Math.round(min ?? max));
  const normalizedMax = Math.max(normalizedMin, Math.round(max ?? normalizedMin));
  return { min: normalizedMin, max: normalizedMax };
}

function getAbsoluteScreenBounds(options) {
  const bounds = options.screenBounds && typeof options.screenBounds === 'object'
    ? options.screenBounds
    : {};
  const width = toFiniteNumber(bounds.width ?? options.screenWidth);
  const height = toFiniteNumber(bounds.height ?? options.screenHeight);
  const left = toFiniteNumber(bounds.left ?? options.screenLeft) ?? 0;
  const top = toFiniteNumber(bounds.top ?? options.screenTop) ?? 0;

  if (!width || !height || width <= 0 || height <= 0) {
    return { left, top };
  }

  return {
    left: Math.round(left),
    top: Math.round(top),
    width: Math.round(width),
    height: Math.round(height)
  };
}

function getClickFns(bindings, button) {
  const normalized = normalizeButton(button);
  if (normalized === 'right') {
    return {
      click: bindings.HKMRightClick,
      down: bindings.HKMRightDown,
      up: bindings.HKMRightUp
    };
  }
  if (normalized === 'middle') {
    return {
      click: bindings.HKMMiddleClick,
      down: bindings.HKMMiddleDown,
      up: bindings.HKMMiddleUp
    };
  }
  return {
    click: bindings.HKMLeftClick,
    down: bindings.HKMLeftDown,
    up: bindings.HKMLeftUp
  };
}

function createDeviceInfo(deviceId, options = {}) {
  const vendorId = options.vid && options.vid !== HKM_IGNORE_VID_PID ? String(options.vid) : '';
  const productId = options.pid && options.pid !== HKM_IGNORE_VID_PID ? String(options.pid) : '';
  return {
    path: String(deviceId),
    deviceId,
    kind: 'wyhkm',
    manufacturer: 'Wuya',
    serialNumber: '',
    vendorId,
    productId,
    friendlyName: `Wuya HKM device ${deviceId}`,
    isUsbLike: true,
    dllPath: options.dllPath || getDefaultDllPath(options)
  };
}

async function listDevices(options = {}) {
  const merged = { ...DEFAULT_OPTIONS, ...options };
  if (process.platform !== 'win32') {
    return [];
  }

  const bindings = loadBindings(merged);
  const data = bindings.HKMSearchDeviceAll(merged.vid, merged.pid, merged.deviceType);
  if (!data) {
    const deviceId = bindings.HKMSearchDevice(merged.vid, merged.pid, merged.deviceType);
    return isFail(deviceId) ? [] : [createDeviceInfo(deviceId, merged)];
  }

  try {
    const count = bindings.HKMGetDataCount(data);
    const devices = [];
    for (let index = 0; index < count; index += 1) {
      const deviceId = bindings.HKMGetDataUnitInt(data, index);
      if (!isFail(deviceId)) {
        devices.push(createDeviceInfo(deviceId, merged));
      }
    }
    return devices;
  } finally {
    bindings.HKMFreeData(data);
  }
}

async function detectWyHkmDevices(options = {}) {
  return listDevices(options);
}

async function probeWyHkmDevice(deviceId, options = {}) {
  const merged = { ...DEFAULT_OPTIONS, ...options };
  if (process.platform !== 'win32') {
    return {
      available: false,
      kind: 'wyhkm',
      reason: 'Wuya HKM DLL can only run on Windows',
      candidates: []
    };
  }

  const bindings = loadBindings(merged);
  const resolvedDeviceId = typeof deviceId === 'number'
    ? deviceId
    : bindings.HKMSearchDevice(merged.vid, merged.pid, merged.deviceType);

  if (isFail(resolvedDeviceId)) {
    return {
      available: false,
      kind: 'wyhkm',
      reason: 'No Wuya HKM device found',
      candidates: []
    };
  }

  const handle = bindings.HKMOpen(resolvedDeviceId, merged.dpiMode);
  if (!handle) {
    const code = toErrorCode(bindings, handle);
    return {
      available: false,
      kind: 'wyhkm',
      deviceId: resolvedDeviceId,
      device: createDeviceInfo(resolvedDeviceId, merged),
      errorCode: code,
      errorHex: typeof code === 'number' ? `0x${code.toString(16)}` : undefined,
      reason: 'Failed to open Wuya HKM device'
    };
  }

  try {
    return {
      available: true,
      kind: 'wyhkm',
      deviceId: resolvedDeviceId,
      portPath: String(resolvedDeviceId),
      device: createDeviceInfo(resolvedDeviceId, merged)
    };
  } finally {
    bindings.HKMClose(handle);
  }
}

async function probeInputDevice(deviceId, options = {}) {
  return probeWyHkmDevice(deviceId, options);
}

async function autoDetectWyHkm(options = {}) {
  const candidates = await detectWyHkmDevices(options);
  if (candidates.length === 0) {
    return {
      available: false,
      kind: 'wyhkm',
      candidates,
      reason: process.platform === 'win32'
        ? 'No Wuya HKM device found'
        : 'Wuya HKM DLL can only run on Windows'
    };
  }

  const probe = await probeWyHkmDevice(candidates[0].deviceId, options);
  return {
    ...probe,
    candidates
  };
}

async function autoDetectInputDevice(options = {}) {
  return autoDetectWyHkm(options);
}

function createInputFromDetectedDevice(detection, options = {}) {
  if (!detection || !detection.available) {
    throw new Error(detection?.reason || 'No available Wuya HKM device detected');
  }

  return createWyHkmInput({
    ...options,
    deviceId: detection.deviceId ?? Number(detection.portPath)
  });
}

async function createInputFromAutoDetect(options = {}) {
  const detection = await autoDetectInputDevice(options);
  return {
    detection,
    input: createInputFromDetectedDevice(detection, options)
  };
}

function createWyHkmInput(userOptions = {}) {
  const options = { ...DEFAULT_OPTIONS, ...userOptions };
  let bindings = null;
  let handle = null;
  let connected = false;
  let currentDeviceId = options.deviceId;
  let lastError = '';

  function getBindings() {
    if (!bindings) {
      bindings = loadBindings(options);
    }
    return bindings;
  }

  async function ensureDeviceId() {
    if (typeof currentDeviceId === 'number' && !Number.isNaN(currentDeviceId)) {
      return currentDeviceId;
    }

    const api = getBindings();
    const found = api.HKMSearchDevice(options.vid, options.pid, options.deviceType);
    if (isFail(found)) {
      throw new Error('No Wuya HKM device found');
    }
    currentDeviceId = found;
    return currentDeviceId;
  }

  async function connect() {
    if (connected && handle) {
      return;
    }

    const api = getBindings();
    const deviceId = await ensureDeviceId();
    const opened = api.HKMOpen(deviceId, options.dpiMode);
    if (!opened) {
      lastError = 'Failed to open Wuya HKM device';
      throwHkmError(lastError, api, opened);
    }

    handle = opened;
    connected = true;
    lastError = '';

    const keyInterval = normalizeKeyIntervalOptions(options);
    if (keyInterval) {
      assertResult(
        api.HKMSetKeyInterval(handle, keyInterval.min, keyInterval.max),
        'HKMSetKeyInterval failed'
      );
    }
  }

  async function disconnect() {
    if (!handle) {
      connected = false;
      return;
    }

    const api = getBindings();
    const currentHandle = handle;
    handle = null;
    connected = false;
    api.HKMClose(currentHandle);
  }

  async function getHealth() {
    if (!connected || !handle) {
      return {
        connected: false,
        portPath: currentDeviceId === undefined ? undefined : String(currentDeviceId),
        deviceId: currentDeviceId,
        reason: lastError || 'Wuya HKM not connected'
      };
    }

    try {
      const api = getBindings();
      const isOpen = toBool(api.HKMIsOpen(handle, 0));
      return {
        connected: isOpen,
        portPath: currentDeviceId === undefined ? undefined : String(currentDeviceId),
        deviceId: currentDeviceId,
        mouseMode: api.HKMGetMouseMode(handle),
        reason: isOpen ? undefined : 'Wuya HKM handle is not open'
      };
    } catch (error) {
      return {
        connected: false,
        portPath: currentDeviceId === undefined ? undefined : String(currentDeviceId),
        deviceId: currentDeviceId,
        reason: error?.message || String(error)
      };
    }
  }

  function assertResult(ok, message) {
    if (!toBool(ok)) {
      lastError = message;
      throwHkmError(message, getBindings(), handle);
    }
  }

  async function moveTo(targetX, targetY, _getCursorPos) {
    await connect();
    const api = getBindings();
    const x = Math.round(targetX);
    const y = Math.round(targetY);

    if (toBool(api.HKMMoveTo(handle, x, y))) {
      return;
    }

    let moveToError = getHkmErrorMessage('HKMMoveTo failed', api, handle);
    const screenBounds = getAbsoluteScreenBounds(options);
    if (screenBounds.width && screenBounds.height) {
      const screenResSet = toBool(
        api.HKMSetAbsMouseScrnRes(handle, screenBounds.width, screenBounds.height)
      );
      if (screenResSet && toBool(api.HKMMoveTo(handle, x, y))) {
        return;
      }
      moveToError = screenResSet
        ? getHkmErrorMessage('HKMMoveTo failed after HKMSetAbsMouseScrnRes', api, handle)
        : getHkmErrorMessage('HKMSetAbsMouseScrnRes failed', api, handle);
    }

    const current = typeof _getCursorPos === 'function'
      ? await _getCursorPos()
      : await getCursorPos();
    const dx = Math.round(targetX - current.x);
    const dy = Math.round(targetY - current.y);
    const moveRelativeFn = api.HKMMoveR2 || api.HKMMoveR;
    assertResult(
      moveRelativeFn(handle, dx, dy),
      `${moveToError}; relative fallback failed`
    );
  }

  async function moveRelative(dx, dy) {
    await connect();
    assertResult(
      (getBindings().HKMMoveR2 || getBindings().HKMMoveR)(handle, Math.round(dx), Math.round(dy)),
      'relative mouse move failed'
    );
  }

  async function click(button = 'left', clickOptions = {}) {
    await connect();
    const api = getBindings();
    const fns = getClickFns(api, button);
    const normalizedClickOptions = normalizeClickOptions(clickOptions, options);

    for (let index = 0; index < normalizedClickOptions.repeat; index += 1) {
      if (normalizedClickOptions.holdMs > 0) {
        assertResult(fns.down(handle), 'mouse button down failed');
        await sleep(normalizedClickOptions.holdMs);
        assertResult(fns.up(handle), 'mouse button up failed');
      } else {
        assertResult(fns.click(handle), 'mouse click failed');
      }

      if (index < normalizedClickOptions.repeat - 1) {
        await sleep(normalizedClickOptions.intervalMs);
      }
    }
  }

  async function moveAndClick(targetX, targetY, getCursorPos, button = 'left') {
    await moveTo(targetX, targetY, getCursorPos);
    await click(button);
  }

  async function keyToggle(key, state) {
    await connect();
    const keyName = normalizeKey(key);
    if (!keyName) {
      throw new Error(`Unsupported Wuya HKM key: ${key}`);
    }

    const api = getBindings();
    const fn = state === 'down' ? api.HKMKeyDown : api.HKMKeyUp;
    assertResult(fn(handle, keyName), `HKMKey${state === 'down' ? 'Down' : 'Up'} failed for ${keyName}`);
  }

  async function keyTap(key, modifiers = []) {
    await connect();

    const api = getBindings();
    const keyName = normalizeKey(key);
    if (!keyName) {
      throw new Error(`Unsupported Wuya HKM keyTap key: ${key}`);
    }

    const normalizedModifiers = Array.isArray(modifiers)
      ? modifiers.map(normalizeKey).filter(Boolean)
      : [];

    for (const modifier of normalizedModifiers) {
      assertResult(api.HKMKeyDown(handle, modifier), `modifier down failed for ${modifier}`);
    }
    assertResult(api.HKMKeyPress(handle, keyName), `HKMKeyPress failed for ${keyName}`);
    for (const modifier of normalizedModifiers.reverse()) {
      assertResult(api.HKMKeyUp(handle, modifier), `modifier up failed for ${modifier}`);
    }
  }

  async function pasteShortcut(platform) {
    const modifier = normalizePlatform(platform) === 'darwin' ? 'command' : 'control';
    await keyTap('v', [modifier]);
    await keyToggle(modifier, 'up');
  }

  async function typeString(text) {
    await connect();
    assertResult(
      getBindings().HKMOutputString(handle, String(text ?? '')),
      'HKMOutputString failed'
    );
  }

  async function mouseWheel(count) {
    await connect();
    assertResult(
      getBindings().HKMMouseWheel(handle, Math.round(count)),
      'HKMMouseWheel failed'
    );
  }

  async function getCursorPos() {
    await connect();
    const value = getBindings().HKMGetCursorPos2(handle);
    return {
      x: value & 0xffff,
      y: (value >>> 16) & 0xffff
    };
  }

  async function getMouseMode() {
    await connect();
    return getBindings().HKMGetMouseMode(handle);
  }

  return {
    connect,
    disconnect,
    listDevices,
    getHealth,
    moveTo,
    click,
    moveAndClick,
    keyTap,
    keyToggle,
    pasteShortcut,
    typeString,
    _debug: {
      getCursorPos,
      getMouseMode,
      moveRelative,
      mouseWheel
    }
  };
}

module.exports = {
  autoDetectInputDevice,
  autoDetectWyHkm,
  createInputFromAutoDetect,
  createInputFromDetectedDevice,
  createWyHkmInput,
  detectWyHkmDevices,
  listDevices,
  probeInputDevice,
  probeWyHkmDevice
};
